def transform(grid):
    h, w = len(grid), len(grid[0])
    # Rotate clockwise, filling each 1-marker from its local surrounding color.
    src = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if src[r][c] == 1:
                counts = {}
                for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and src[nr][nc] != 1:
                        v = src[nr][nc]
                        counts[v] = counts.get(v, 0) + 1
                if counts:
                    src[r][c] = max(counts, key=counts.get)
    return [[src[h - 1 - c][r] for c in range(h)] for r in range(w)]
