def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # Replace each marker by the closest surrounding non-marker color.
    for r, c in markers:
        best = None
        best_dist = h + w + 1
        for rr in range(h):
            for cc in range(w):
                if grid[rr][cc] != 1:
                    d = abs(rr-r) + abs(cc-c)
                    if d < best_dist:
                        best_dist = d
                        best = grid[rr][cc]
        if best is not None:
            out[r][c] = best
    return out
